def start(self):
    import threading
    import time
    from udi_interface import LOGGER
    from timer_node import TimerNode

    count = 20
    self.timer_nodes = []
    for i in range(1, count + 1):
        address = self.poly.getValidAddress('timer_%d' % i)
        name = self.poly.getValidName('Timer_%d' % i)
        node = TimerNode(self.poly, self.address, address, name)
        self.poly.addNode(node)
        self.timer_nodes.append(node)

    # A restart always begins every timer at 0, whatever IoX last held.
    for node in self.timer_nodes:
        try:
            if hasattr(self.poly, 'waitForNode'):
                self.poly.waitForNode(node.address)
        except Exception as ex:
            LOGGER.warning('waitForNode(%s) failed: %s', node.address, ex)
        node.reset_state()

    self._timer_stop = threading.Event()

    def tick_loop():
        next_t = time.monotonic() + 1.0
        while not self._timer_stop.is_set():
            delay = next_t - time.monotonic()
            if delay > 0 and self._timer_stop.wait(delay):
                break
            next_t += 1.0
            if time.monotonic() - next_t > 5.0:
                # fell far behind (e.g. the host stalled): resume ticking, don't burst
                next_t = time.monotonic() + 1.0
            for node in list(self.timer_nodes):
                try:
                    node.tick()
                except Exception:
                    LOGGER.exception('tick failed for %s', node.address)

    self._timer_thread = threading.Thread(target=tick_loop, name='timer-tick', daemon=True)
    self._timer_thread.start()
    LOGGER.info('Timer started: %d timer nodes, all at 0', count)

override_bodies.stop:
def stop(self):
    from udi_interface import LOGGER
    event = getattr(self, '_timer_stop', None)
    if event is not None:
        event.set()
    thread = getattr(self, '_timer_thread', None)
    if thread is not None:
        thread.join(timeout=3)
    LOGGER.info('Timer stopped')

